const docs = Array.isArray(msg.payload) ? msg.payload : [];

// Build table-ready asset list (FR-ACM-04: include linkedAssets flags only, not bodies)
const assets = docs.map(d => {
    const hasOriginal = d.originalForm !== undefined && d.originalForm !== null;
    const hasTransformed = d.transformedForm !== undefined && d.transformedForm !== null;
    // The harvester stores the source catalogue as sourceCatalogue /
    // sourceCatalogueName; reading d.catalogue alone renders every row as '-'.
    const sourceCatalogueName = d.sourceCatalogueName || d.sourceCatalogue || d.catalogue || d.name || '';
    const strategy = d.transformationStrategy || (d.catalogueTransform && d.catalogueTransform.strategy) || d.strategy || '';
    return {
        id: d.uniqueId,
        assets: d.title || '-',
        type: d.type || 'Dataset',
        name: sourceCatalogueName || '-',
        sourceCatalogue: sourceCatalogueName || '-',
        sourceCatalogueName: sourceCatalogueName || '-',
        catalogue: sourceCatalogueName || '-',
        domain: d.domain || sourceCatalogueName || '-',
        updated: (d.harvestedAt || d.createdAt || '-').replace('T', ' ').slice(0, 19),
        harvestedAt: d.harvestedAt || d.createdAt || '',
        protocol: d.protocol || '',
        integrationStatus: d.status || 'Active',
        harvestRunId: d.harvestRunId || '',
        sourceAssetId: d.sourceAssetId || '',
        strategy: strategy,
        transformationStrategy: strategy,
        catalogueId: d.catalogueId || '',
        harvestScope: d.harvestScope || {},
        uniqueId: d.uniqueId,
        linkedAssets: { hasOriginal: hasOriginal, hasTransformed: hasTransformed },
        crawledFrom: d.crawledFrom || '',
        crawlDepth: (typeof d.crawlDepth === 'number') ? d.crawlDepth : null,
        crawlReferenceUri: d.crawlReferenceUri || '',
        crawlReferenceField: d.crawlReferenceField || '',
        sourceCatalogueId: d.sourceCatalogueId || ''
    };
});

assets.sort((a, b) => (b.updated || '').localeCompare(a.updated || ''));

// Compute stats
const runIds = new Set();
for (const d of docs) { if (d.harvestRunId) runIds.add(d.harvestRunId); }

msg.response = {
    action: 'getLocalCatalogue',
    status: 'success',
    assets: assets,
    totalAssets: assets.length,
    totalRuns: runIds.size
};
delete msg.payload;
return msg;

const uid = msg.data?.uniqueId || msg.data?.assetId || '';
msg._assetId = uid;
msg.operation = 'find';
msg.collection = 'lc_assets';
msg.payload = [{ uniqueId: uid }];
return msg;

const docs = Array.isArray(msg.payload) ? msg.payload : [];
const raw = docs[0] || null;
const form = (msg.data && typeof msg.data.form === 'string') ? msg.data.form : 'transformed';

let asset = null;
if (raw) {
    const hasOriginal = raw.originalForm !== undefined && raw.originalForm !== null;
    const hasTransformed = raw.transformedForm !== undefined && raw.transformedForm !== null;
    const linkedAssets = { hasOriginal: hasOriginal, hasTransformed: hasTransformed };

    // Shallow clone without the heavy form bodies
    const base = {};
    for (const k in raw) {
        if (k !== 'originalForm' && k !== 'transformedForm') base[k] = raw[k];
    }
    base.linkedAssets = linkedAssets;

    if (form === 'original') {
        asset = Object.assign({}, base, {
            viewingForm: 'original',
            originalForm: raw.originalForm || null
        });
    } else if (form === 'both') {
        asset = Object.assign({}, base, {
            viewingForm: 'both',
            originalForm: raw.originalForm || null,
            transformedForm: raw.transformedForm || null
        });
    } else {
        // default: transformed
        asset = Object.assign({}, base, {
            viewingForm: 'transformed',
            transformedForm: raw.transformedForm || null
        });
    }
}

msg.response = {
    action: 'getLocalAssetDetail',
    status: 'success',
    form: form,
    asset: asset
};
delete msg.payload;
delete msg._assetId;
return msg;

const uid = msg.data?.uniqueId;
if (!uid) {
    msg.response = {
        action: 'deleteLocalAsset',
        status: 'error',
        message: 'Missing uniqueId'
    };
    delete msg.payload;
    return [null, msg];
}
msg.operation = 'deleteOne';
msg.collection = 'lc_assets';
msg.payload = { uniqueId: uid };
return [msg, null];

msg.response = {
    action: 'deleteLocalAsset',
    status: 'success'
};
delete msg.payload;
return msg;

const uid = msg.data?.uniqueId;
const patch = msg.data?.patch || {};
if (!uid) {
    msg.response = {
        action: 'updateLocalAsset',
        status: 'error',
        message: 'Missing uniqueId'
    };
    delete msg.payload;
    return [null, msg];
}
patch.updatedAt = new Date().toISOString();
msg.operation = 'updateOne';
msg.collection = 'lc_assets';
msg.payload = [
    { uniqueId: uid },
    { $set: patch }
];
return [msg, null];

msg.response = {
    action: 'updateLocalAsset',
    status: 'success'
};
delete msg.payload;
return msg;

const docs = Array.isArray(msg.payload) ? msg.payload : [];

// One field mapping for every provenance view. Older rows only carry runId,
// timestamp and catalogue, so the canonical names are filled in from the run.
function provenanceRow(p, run) {
    const catName = p.sourceCatalogueName || p.catalogue || p.remoteCatalogueName || '';
    const catId = p.sourceCatalogueId || p.catalogueId || p.remoteCatalogueId || '';
    const runId = p.harvestRunId || p.runId || (run && run.uniqueId) || '';
    const at = p.harvestedAt || p.timestamp || p.harvestDate || (run && run.startedAt) || '';
    const strategy = p.transformationStrategy || p.strategy || '';
    const evidence = (run && Array.isArray(run.protocolEvidence)) ? run.protocolEvidence : [];
    const ev = evidence.find(e => e && ((catId && e.catalogueId === catId) || (catName && e.catalogueName === catName)));
    return Object.assign({}, p, {
        runId: runId,
        harvestRunId: runId,
        catalogue: catName,
        catalogueName: catName,
        sourceCatalogueName: catName,
        remoteCatalogueName: catName,
        sourceCatalogueId: catId,
        remoteCatalogueId: catId,
        harvestedAt: at,
        harvestDate: at,
        timestamp: at,
        protocol: p.protocol || (ev && ev.protocol) || '',
        strategy: strategy,
        transformationStrategy: strategy
    });
}

const provenance = [];
for (const d of docs) {
    if (Array.isArray(d.provenance)) {
        for (const p of d.provenance) provenance.push(provenanceRow(p, d));
    }
}
msg.response = {
    action: 'getLocalProvenance',
    status: 'success',
    provenance: provenance,
    total: provenance.length
};
delete msg.payload;
return msg;

const docs = Array.isArray(msg.payload) ? msg.payload : [];

const runIds = new Set();
const catalogueIds = new Set();
const statusCounts = { Active: 0, Warning: 0, Error: 0, Archived: 0 };

for (const d of docs) {
    if (d.harvestRunId) runIds.add(d.harvestRunId);
    if (d.catalogueId || d.catalogue) catalogueIds.add(d.catalogueId || d.catalogue);
    const s = d.status || 'Active';
    if (statusCounts[s] !== undefined) statusCounts[s]++;
    else statusCounts.Active++;
}

msg.response = {
    action: 'getLocalStats',
    status: 'success',
    totalAssets: docs.length,
    totalRuns: runIds.size,
    linkedCatalogues: catalogueIds.size,
    totalProvenance: docs.length,
    statusCounts: statusCounts,
    warningCount: statusCounts.Warning,
    errorCount: statusCounts.Error
};
delete msg.payload;
return msg;

msg.collection = "dcm_heartbeats";
msg.operation = "updateOne";
msg.payload = [
  { module: "LocalCatalogue" },
  { $set: { module: "LocalCatalogue", at: new Date().toISOString() } },
  { upsert: true }
];
return msg;

function unwrap(value) {
  return Array.isArray(value) ? (value[0] || null) : value;
}
function tokenFromMessage() {
  let token = (msg.auth && msg.auth.userToken) || msg._token || (msg.data && msg.data.token) || "";
  if (!token && msg.payload && typeof msg.payload === "object") {
    token = msg.payload.token || (msg.payload.auth && msg.payload.auth.userToken) || msg.payload._token || "";
  }
  if (!token && msg.topic && String(msg.topic).indexOf("|") !== -1) {
    token = String(msg.topic).split("|")[1] || "";
  }
  return String(token || "");
}
function reject(code, message) {
  const action = msg._rbacOriginalType || msg.type || "unknown";
  msg.type = action;
  msg.response = { action, status: "error", ok: false, code, error: code, message };
  delete msg.payload;
  delete msg.collection;
  delete msg.operation;
  ["_rbacStep","_rbacOriginalType","_rbacOriginalPayload","_rbacOriginalData","_rbacOriginalTopic","_rbacSessionToken"].forEach(k => delete msg[k]);
  return [null, null, msg];
}

const step = Number(msg._rbacStep || 0);
if (step === 0) {
  const token = tokenFromMessage();
  msg._rbacOriginalType = msg.type || "";
  msg._rbacOriginalPayload = msg.payload;
  msg._rbacOriginalData = msg.data;
  msg._rbacOriginalTopic = msg.topic || "";
  if (!token) return reject("not_authenticated", "Not authenticated - no session token.");
  msg._rbacStep = 1;
  msg._rbacSessionToken = token;
  msg.collection = "auth_sessions";
  msg.operation = "findOne";
  msg.payload = { token };
  return [msg, null, null];
}

if (step === 1) {
  const session = unwrap(msg.payload);
  const now = new Date();
  if (!session || !session.user || (session.expiresAt && new Date(session.expiresAt) <= now)) {
    return reject("not_authenticated", "Session expired or invalid.");
  }
  const user = session.user;
  const status = String(user.status || "active");
  if (status === "disabled" || status === "deleted") {
    return reject("account_disabled", "The account is disabled.");
  }
  if (user.expiresAt && new Date(user.expiresAt) <= now) {
    return reject("account_expired", "The account has expired.");
  }
  msg.auth = {
    username: user.username || "",
    userId: user.id || session.userId || "",
    userToken: msg._rbacSessionToken,
    role: user.role || (Array.isArray(user.roles) && user.roles[0]) || "viewer",
    roles: Array.isArray(user.roles) ? user.roles : [],
    permissions: Array.isArray(user.permissions) ? user.permissions : [],
    accessAreas: Array.isArray(user.accessAreas) ? user.accessAreas : []
  };
  msg.type = msg._rbacOriginalType;
  msg.payload = msg._rbacOriginalPayload;
  msg.data = msg._rbacOriginalData;
  msg.topic = msg._rbacOriginalTopic;
  msg._callerUsername = user.username || "unknown";
  ["_rbacStep","_rbacOriginalType","_rbacOriginalPayload","_rbacOriginalData","_rbacOriginalTopic","_rbacSessionToken","collection","operation"].forEach(k => delete msg[k]);
  return [null, msg, null];
}

return reject("auth_error", "Unexpected authorization state.");

const action = String(msg.type || "");
const auth = msg.auth || {};
const permissions = Array.isArray(auth.permissions) ? auth.permissions : [];
const roles = Array.isArray(auth.roles) ? auth.roles : [];
const requiredPermission = {
  "getLocalCatalogue": "local.catalogue.read",
  "getLocalAssetDetail": "local.catalogue.read",
  "deleteLocalAsset": "catalogue.registry.delete",
  "updateLocalAsset": "catalogue.registry.update",
  "getLocalProvenance": "local.catalogue.read",
  "getLocalStats": "local.catalogue.read"
}[action] || null;
const isAdmin = auth.role === "admin" || roles.includes("admin");
const hasPermission = requiredPermission && (
  permissions.includes(requiredPermission) ||
  (isAdmin && permissions.includes("*"))
);

if (hasPermission) return [msg, null, null];

const reason = requiredPermission ? "missing_permission" : "unmapped_action";
const message = requiredPermission
  ? "Insufficient permissions. Required: " + requiredPermission
  : "Action is not permitted by the backend authorization policy.";
const audit = {
  collection: "dcm_audit_log",
  operation: "insertOne",
  payload: {
    timestamp: new Date().toISOString(),
    actor: auth.username || "unknown",
    actorId: auth.userId || null,
    area: "localCatalogue",
    action: "access.denied",
    target: action || "unknown",
    after: { requiredPermission, reason },
    result: "denied",
    source: "rbac"
  }
};
msg.response = {
  action: action || "unknown",
  status: "error",
  ok: false,
  code: "permission_denied",
  error: "permission_denied",
  message,
  requiredPermission
};
delete msg.payload;
return [null, audit, msg];
